  rsample::initial_split(read.csv("~/Downloads/student_exam_performance_dataset.csv"), prop = 0.2, strata = pass_fail) |&gt;
  rsample::training() |&gt;
  mutate(
    pass_fail = as.numeric(pass_fail == "Pass")
