data_FA_pred = list(
  X = X,
  n_row = nrow(X),
  n_col = ncol(X),
  n_fac = 3,
  n_alpha_free = max(contr),
  sigma_shape = .1,
  sigma_rate  = .1,
  alpha_status = contr,
  is_missing = is.missing,
